    const ignoredPlatforms = typeof payload.ignore === "boolean" ? undefined : payload.ignore;
    const aliases = $i(PlatformType.values()).map(type => [type, payload[type] ? asString(payload[type]) : undefined]).filter(([, id]) => id).toMap();
    const type = (dependency?.incompatible && DependencyType.INCOMPATIBLE ||
        dependency?.embedded && DependencyType.EMBEDDED ||
        dependency?.mandatory && DependencyType.REQUIRED ||
        DependencyType.OPTIONAL);
